pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 feeRate) public {
        // admissibility: feeRate must be <= 5000 for initialize to succeed
        vm.assume(feeRate <= 5000);
        // first call must succeed to set state
        try c.initialize(address(0), address(0), 1, 1, 0, feeRate, bytes32(0), false, false) {
        } catch {
            vm.assume(false);
        }
        // second call is expected to revert with AlreadyInitialized
        try c.initialize(address(0), address(0), 1, 1, 0, feeRate, bytes32(0), false, false) {
            vm.assume(false);
        } catch {
        }
        // after first successful call, feeRate must equal the argument
        assertTrue(c.feeRate() == feeRate);
    }
}

